const dictionaries: Record<Locale,Record<MessageKey,string>> = {en,uk,ru,fr,es,de};
export function translate(locale:Locale,key:MessageKey,parameters?:Record<string,string|number>):string {
  const message = dictionaries[locale][key] || en[key];
  return message.replace(/\{(\w+)\}/g, (match,name:string)=>parameters?.[name] === undefined ? match : String(parameters[name]));
}
